INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Marktsituation in der IT immer stabil ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Sie schwankt je nach Trends"}, {"text": "Ja", "correct": false, "because": "Zu statisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich die Marktsituation für eine IT-Firma analysiere?', 3, '[{"text": "Marktdaten", "correct": true, "because": "Basis für Analyse"}, {"text": "Schnellste Durchführung", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Marktsituation in der IT?', 5, '[{"text": "Wettbewerb", "correct": true, "because": "Bestimmt Marktanteile"}, {"text": "Technologische Trends", "correct": true, "because": "Verändern Nachfrage"}, {"text": "Büromöbel", "correct": false, "because": "Kein Marktfaktor"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Marktsituation wirkt sich auf IT-Strategien aus. b) Sie bleibt immer konstant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sie verändert sich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich die Marktsituation für eine IT-Firma bewerte?', 4, '[{"text": "Wettbewerber", "correct": false, "because": "Wichtiger Einfluss"}, {"text": "Kundennachfrage", "correct": false, "because": "Bestimmt Markt"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Marktfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Marktsituation nur lokale IT-Firmen betrifft?', 2, '[{"text": "Nein", "correct": true, "because": "Auch global relevant"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich die Marktsituation in der IT analysiere?', 3, '[{"text": "Marktchancen erkennen", "correct": true, "because": "Für Strategie"}, {"text": "Schnellste Analyse", "correct": false, "because": "Qualität wichtiger"}, {"text": "Weniger Daten", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden helfen, die Marktsituation in der IT zu bewerten?', 5, '[{"text": "Marktforschung", "correct": true, "because": "Liefert Daten"}, {"text": "Wettbewerbsanalyse", "correct": true, "because": "Vergleicht Anbieter"}, {"text": "Büroplanung", "correct": false, "because": "Irrelevant"}, {"text": "Farbanalyse", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Die Marktsituation beeinflusst IT-Investitionen. b) Sie ist immer vorhersehbar. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schwer vorhersehbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um die Marktsituation in der IT zu analysieren?', 4, '[{"text": "Marktdaten", "correct": false, "because": "Kernbestandteil"}, {"text": "Kundenfeedback", "correct": false, "because": "Zeigt Bedarf"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Markt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Marktsituation immer stabil?', 2, '[{"text": "Nein", "correct": true, "because": "Schwankt je nach Bedingungen"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Analyse der Marktsituation?', 4, '[{"text": "Strategische Planung", "correct": true, "because": "Passt an Markt an"}, {"text": "Wettbewerbsvorteil", "correct": true, "because": "Erkennt Chancen"}, {"text": "Schnellere Projekte", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Marktsituation nur für große IT-Firmen relevant ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch KMU betroffen"}, {"text": "Ja", "correct": false, "because": "Für alle wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um die Marktsituation für eine IT-Firma zu bewerten?', 3, '[{"text": "Marktberichte", "correct": true, "because": "Liefern Daten"}, {"text": "Schnellste Software", "correct": false, "because": "Genauigkeit wichtiger"}, {"text": "Bunte Diagramme", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Marktsituation zeigt Wettbewerbsstärke. b) Sie ist immer statisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dynamisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei der Marktsituation in der IT?', 5, '[{"text": "Kundennachfrage", "correct": true, "because": "Beeinflusst Markt"}, {"text": "Technologietrends", "correct": true, "because": "Verändern Bedingungen"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich die Marktsituation für eine IT-Firma analysiere?', 3, '[{"text": "Wettbewerbsaktionen", "correct": false, "because": "Wichtiger Faktor"}, {"text": "Marktentwicklung", "correct": false, "because": "Bestimmt Chancen"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Marktfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Marktsituation nur für neue IT-Firmen relevant?', 3, '[{"text": "Nein", "correct": true, "because": "Auch bestehende betroffen"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Marktsituation nur lokale Märkte umfasst?', 2, '[{"text": "Nein", "correct": true, "because": "Auch global"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend, um die Marktsituation zu verstehen?', 4, '[{"text": "Aktuelle Marktdaten", "correct": true, "because": "Sichert Relevanz"}, {"text": "Schnellste Analyse", "correct": false, "because": "Qualität zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
